/bin/bash -lc "cd [workspace path] && python3 -c \"
import numpy as np
d = np.load('source_pixels.npz')['rgb']

def centroids(frames):
    cyan_pos = []
    yellow_pos = []
    for f in frames:
        r, g, b = f[...,0].astype(int), f[...,1].astype(int), f[...,2].astype(int)
        cyan = (r < 120) & (g > 150) & (b > 150)
        yellow = (r > 150) & (g > 120) & (b < 100)
        def cent(mask):
            ys, xs = np.nonzero(mask)
            if len(xs)==0: return (np.nan, np.nan, np.nan)
            return (xs.mean(), ys.mean(), float(len(xs)))
        cyan_pos.append(cent(cyan))
        yellow_pos.append(cent(yellow))
    return np.array(cyan_pos), np.array(yellow_pos)

cy, yl = centroids(d)
np.set_printoptions(suppress=True, linewidth=200)
print('frame  cx    cy   npix |   yx    yy   npix')
for i in range(96):
    print(f'{i:3d}  {cy[i,0]:6.2f} {cy[i,1]:6.2f} {int(cy[i,2]):5d} | {yl[i,0]:6.2f} {yl[i,1]:6.2f} {int(yl[i,2]):5d}')
\" 2>&1 | head -100"
